local ChandelierMaker = {}
local PRODUCTS = {
    iron_chandelier = { name = "Železni luster", ironCost = 3, waxCost = 1, time = 4, cost = 50, lightRadius = 30, prestige = 3, description = "Železni luster za dvorane." },
    brass_chandelier = { name = "Medeninast luster", brassCost = 3, waxCost = 1, time = 6, cost = 120, lightRadius = 45, prestige = 6, happiness = 1, description = "Medeninast luster za plemiče." },
    silver_chandelier = { name = "Srebrni luster", silverCost = 2, brassCost = 1, waxCost = 1, glassCost = 1, time = 9, cost = 300, lightRadius = 60, prestige = 12, happiness = 2, description = "Srebrni luster s steklenimi okraski." },
    crystal_chandelier = { name = "Kristalni luster", silverCost = 2, glassCost = 2, waxCost = 1, goldCost = 1, time = 12, cost = 680, lightRadius = 75, prestige = 20, happiness = 4, description = "Kristalni luster za visoke plemiče." },
    gold_leaf_chandelier = { name = "Zlatolistni luster", goldCost = 2, silverCost = 1, glassCost = 2, jewelCost = 1, waxCost = 1, time = 16, cost = 1500, lightRadius = 88, prestige = 32, happiness = 7, description = "Zlatolistni luster z dragulji." },
    royal_grand_chandelier = { name = "Kraljevski veliki luster", goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 1, glassCost = 3, waxCost = 2, time = 22, cost = 3500, lightRadius = 100, prestige = 60, happiness = 14, description = "Veliki kraljevski luster z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Lustrarska delavnica", cost = { gold = 320, wood = 140, stone = 250 }, upkeep = 8, qualityBonus = 5 },
    forge = { name = "Lustrarska kovačija", cost = { gold = 1100, wood = 280, stone = 500, iron = 8 }, upkeep = 28, qualityBonus = 18 },
    crystal_room = { name = "Kristalna soba", cost = { gold = 2600, wood = 400, stone = 800, silver = 40, glass = 8 }, upkeep = 65, qualityBonus = 30 },
    royal_chandelier_atelier = { name = "Kraljevski atelje lustrov", cost = { gold = 11000, wood = 600, stone = 1200, gold = 80, jewel = 25 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 50 },
}
ChandelierMaker.ironStock = 14; ChandelierMaker.brassStock = 12; ChandelierMaker.silverStock = 8; ChandelierMaker.goldStock = 6; ChandelierMaker.glassStock = 12; ChandelierMaker.waxStock = 10; ChandelierMaker.jewelStock = 6; ChandelierMaker.pearlStock = 4
ChandelierMaker.productStock = {}; ChandelierMaker.buildings = {}; ChandelierMaker.maker = nil; ChandelierMaker.activeMaking = {}; ChandelierMaker.totalProducts = 0; ChandelierMaker.dayTimer = 0
function ChandelierMaker.init() ChandelierMaker.ironStock=14; ChandelierMaker.brassStock=12; ChandelierMaker.silverStock=8; ChandelierMaker.goldStock=6; ChandelierMaker.glassStock=12; ChandelierMaker.waxStock=10; ChandelierMaker.jewelStock=6; ChandelierMaker.pearlStock=4; ChandelierMaker.productStock={}; ChandelierMaker.buildings={}; ChandelierMaker.maker=nil; ChandelierMaker.activeMaking={}; ChandelierMaker.totalProducts=0; ChandelierMaker.dayTimer=0; print("[ChandelierMaker] Royal Chandelier Maker System initialized (6 products, 4 buildings)") end
function ChandelierMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ChandelierMaker.maker={name=n or ("Lustrar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lustrar najet: %s (spretnost: %d)",ChandelierMaker.maker.name,s),"success") end; return true end
function ChandelierMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ChandelierMaker.build(id) local ok,e=ChandelierMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ChandelierMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ChandelierMaker.getQualityBonus() local b=0; for _,bd in ipairs(ChandelierMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ChandelierMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ChandelierMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and ChandelierMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and ChandelierMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ChandelierMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.glassCost and ChandelierMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.waxCost and ChandelierMaker.waxStock<(d.waxCost or 0) then return false,"Premalo voska" end; if d.jewelCost and ChandelierMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ChandelierMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ChandelierMaker.buildings==0 then return false,"Potrebna delavnica" end; if not ChandelierMaker.maker then return false,"Potreben lustrar" end; return true end
function ChandelierMaker.make(pt,qty) qty=qty or 1; local ok,e=ChandelierMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ChandelierMaker.ironStock=ChandelierMaker.ironStock-d.ironCost*qty end; if d.brassCost then ChandelierMaker.brassStock=ChandelierMaker.brassStock-d.brassCost*qty end; if d.silverCost then ChandelierMaker.silverStock=ChandelierMaker.silverStock-d.silverCost*qty end; if d.goldCost then ChandelierMaker.goldStock=ChandelierMaker.goldStock-d.goldCost*qty end; if d.glassCost then ChandelierMaker.glassStock=ChandelierMaker.glassStock-d.glassCost*qty end; if d.waxCost then ChandelierMaker.waxStock=ChandelierMaker.waxStock-d.waxCost*qty end; if d.jewelCost then ChandelierMaker.jewelStock=ChandelierMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ChandelierMaker.pearlStock=ChandelierMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ChandelierMaker.maker then t=math.max(1,t-math.floor(ChandelierMaker.maker.skill/12)) end; table.insert(ChandelierMaker.activeMaking,{id="chandelier_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,lightRadius=d.lightRadius or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ChandelierMaker.completeMaking(m) local q=1.0+(ChandelierMaker.getQualityBonus()/100); if ChandelierMaker.maker then q=q+(ChandelierMaker.maker.skill/150) end; q=math.min(2.5,q); ChandelierMaker.productStock[m.productType]=(ChandelierMaker.productStock[m.productType] or 0)+m.quantity; ChandelierMaker.totalProducts=ChandelierMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ChandelierMaker.maker then ChandelierMaker.maker.itemsMade=ChandelierMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ChandelierMaker.maker.skill=math.min(100,ChandelierMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Luster izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"chandelier.completed",{productName=m.productName,lightRadius=m.lightRadius,prestige=m.prestige,happiness=m.happiness}) end end
function ChandelierMaker.update(dt) if not _G.state then return end; ChandelierMaker.dayTimer=ChandelierMaker.dayTimer+dt; if ChandelierMaker.dayTimer>=30 then ChandelierMaker.dayTimer=0; for i=#ChandelierMaker.activeMaking,1,-1 do local m=ChandelierMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ChandelierMaker.completeMaking(m); table.remove(ChandelierMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ChandelierMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ChandelierMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ChandelierMaker.getStats() return {ironStock=ChandelierMaker.ironStock,brassStock=ChandelierMaker.brassStock,silverStock=ChandelierMaker.silverStock,goldStock=ChandelierMaker.goldStock,glassStock=ChandelierMaker.glassStock,waxStock=ChandelierMaker.waxStock,jewelStock=ChandelierMaker.jewelStock,pearlStock=ChandelierMaker.pearlStock,productStock=ChandelierMaker.productStock,numBuildings=#ChandelierMaker.buildings,hasMaker=ChandelierMaker.maker~=nil,makerName=ChandelierMaker.maker and ChandelierMaker.maker.name or "—",makerSkill=ChandelierMaker.maker and ChandelierMaker.maker.skill or 0,activeMaking=#ChandelierMaker.activeMaking,totalProducts=ChandelierMaker.totalProducts} end
return ChandelierMaker
